// Test helpers: serve the SHIPPED files (public/, generated by scripts/audio/pack-sfx.mjs) to a stubbed fetch, and decode them like a
// browser would (FLAC through the same reference libFLAC the pack script uses; WAV for the dev-only paths).
import { vi } from "vitest";

// node:fs / the .mjs codec via dynamic specifiers so `tsc` needs no @types/node (same pattern as the other sample tests)
const fsName = "node:fs";
const fs = (await import(/* @vite-ignore */ fsName)) as { readFileSync(p: URL): Uint8Array };
const codecName = "../scripts/audio/flac.mjs";
const codec = (await import(/* @vite-ignore */ codecName)) as { decodeFlac(b: Uint8Array): Promise<{ sampleRate: number; pcm: Int16Array }> };

export const readPublic = (url: string): Uint8Array => fs.readFileSync(new URL(`../public/${String(url).replace(/^\.?\//, "")}`, import.meta.url));
const response = (b: Uint8Array) => ({ ok: true, status: 200, json: async () => JSON.parse(new TextDecoder().decode(b)), arrayBuffer: async () => b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength) as ArrayBuffer });
/** fetch stub that answers every URL from public/ */
export const shippedFetch = () => vi.fn(async (url: string) => response(readPublic(url)));

/** decode FLAC (or 16-bit WAV) bytes to float samples at the file's own rate */
export async function decodePcm(ab: ArrayBuffer): Promise<{ sr: number; data: Float32Array }> {
  const b = new Uint8Array(ab);
  if (String.fromCharCode(...b.subarray(0, 4)) === "fLaC") {
    const d = await codec.decodeFlac(b);
    return { sr: d.sampleRate, data: Float32Array.from(d.pcm, (v) => v / 32768) };
  }
  const v = new DataView(ab);
  let p = 12, sr = 0, data = new Float32Array(0);
  while (p + 8 <= b.length) {
    const id = String.fromCharCode(...b.subarray(p, p + 4)), size = v.getUint32(p + 4, true);
    if (id === "fmt ") sr = v.getUint32(p + 12, true);
    if (id === "data") { data = new Float32Array(size / 2); for (let i = 0; i < data.length; i++) data[i] = v.getInt16(p + 8 + i * 2, true) / 32768; }
    p += 8 + size + (size & 1);
  }
  return { sr, data };
}
